def person(name, role, glyph, hp, mp, active=False):
    return f'''<div class="person {'active' if active else ''}">
    <div class="person-top"><span class="avatar">{glyph}</span><div><strong>{name}</strong><small>{role}</small></div><span class="person-tag">{'行動中' if active else '待命'}</span></div>
    <div class="meter-row"><span>HP</span><div class="meter"><i style="width:{hp[0]/hp[1]*100}%"></i></div><b>{hp[0]}/{hp[1]}</b></div>
    <div class="meter-row mp"><span>MP</span><div class="meter"><i style="width:{mp[0]/mp[1]*100}%"></i></div><b>{mp[0]}/{mp[1]}</b></div></div>'''

